//! The reading-order corpus (`fixtures/reading-order/`, generated by `laminapdf-build`'s tests):
//! each file lists its blocks in reading order. Every file is written twice, drawn in reading
//! order (`-ordered`) and in reverse (`-reversed`); layout order must get both right, content
//! order only the first.
#![allow(clippy::unwrap_used, clippy::panic, clippy::indexing_slicing, reason = "test code")]

use laminapdf_extract::{ExtractOptions, ReadingOrder, extract};
use laminapdf_model::{Document, OpenOptions};
use laminapdf_syntax::CancelToken;
use serde_json::Value;

/// Where each expected block's first words appear in the extracted text, in reading order;
/// `None` for a block that can't be found.
fn positions(name: &str, order: ReadingOrder) -> Vec<Option<usize>> {
    let dir = laminapdf_test_fixtures::fixtures_dir().join("reading-order");
    let bytes = std::fs::read(dir.join(format!("{name}.pdf"))).unwrap();
    let expected: Value = serde_json::from_slice(&std::fs::read(dir.join(format!("{name}.json"))).unwrap()).unwrap();
    let doc = Document::open(bytes, OpenOptions::default()).unwrap();
    let out = extract(
        &doc,
        &ExtractOptions::new().with_reading_order(order),
        &CancelToken::new(),
    )
    .unwrap();
    let squeeze = |s: &str| s.split_whitespace().collect::<Vec<_>>().join(" ");
    let text = squeeze(&out.blocks.iter().map(|b| b.text.as_str()).collect::<Vec<_>>().join(" "));
    expected["blocks"]
        .as_array()
        .unwrap()
        .iter()
        .map(|block| {
            let want = squeeze(block["text"].as_str().unwrap());
            let head: String = if want.contains(' ') {
                want.split(' ').take(4).collect::<Vec<_>>().join(" ")
            } else {
                want.chars().take(6).collect()
            };
            text.find(&head)
        })
        .collect()
}

fn in_order(name: &str, order: ReadingOrder) -> bool {
    let found = positions(name, order);
    found.iter().all(Option::is_some) && found.windows(2).all(|w| w[0] < w[1])
}

const LAYOUTS: [&str; 11] = [
    "one-column",
    "two-columns",
    "three-columns",
    "paper",
    "header-footer",
    "sidebar",
    "table",
    "rotated",
    "arabic",
    "hebrew-two-columns",
    "chinese",
];

#[test]
fn layout_order_reads_every_file_in_order_however_it_was_drawn() {
    let wrong: Vec<String> = LAYOUTS
        .iter()
        .flat_map(|name| [format!("{name}-ordered"), format!("{name}-reversed")])
        .filter(|file| !in_order(file, ReadingOrder::Layout))
        .collect();
    assert!(wrong.is_empty(), "out of order: {wrong:?}");
}

#[test]
fn content_order_follows_the_drawing() {
    for name in LAYOUTS {
        assert!(
            in_order(&format!("{name}-ordered"), ReadingOrder::ContentStream),
            "{name}"
        );
    }
    assert!(!in_order("two-columns-reversed", ReadingOrder::ContentStream));
}
